mapper.select:
select distinct date(client_timestamp at time zone 'Asia/Shanghai') as practice_date
from interaction_events
where account_id = #{accountId}
  and client_timestamp >= #{since}
order by practice_date desc
limit 366

select date_trunc(#{truncUnit}, client_timestamp at time zone 'Asia/Shanghai') as bucket_start,
       count(*) as count
from interaction_events
where account_id = #{accountId}
  and client_timestamp >= #{windowStart}
  and client_timestamp < #{windowEnd}
group by bucket_start
order by bucket_start

select count(*) filter (
           where client_timestamp >= #{thisWeekStart}
             and client_timestamp < #{now}
       ) as this_week,
       count(*) filter (
           where client_timestamp >= #{lastWeekStart}
             and client_timestamp < #{thisWeekStart}
       ) as last_week
from interaction_events
where account_id = #{accountId}
